const body = $json.body || $json;
if (!body.vendor && !body.raw_text && !body.invoice_number) {
  throw new Error('Invalid invoice payload: Missing key invoice descriptors');
}
const total = parseFloat(body.total_amount || 0);
const tax = parseFloat(body.tax_amount || 0);
const net = total - tax;

return [{
  json: {
    invoice_id: body.id || 'inv_' + Date.now(),
    vendor: (body.vendor || 'Unknown Vendor').trim(),
    invoice_number: body.invoice_number || 'INV-NA',
    invoice_date: body.invoice_date || new Date().toISOString().split('T')[0],
    total_amount: total,
    tax_amount: tax,
    net_amount: Math.round(net * 100) / 100,
    currency: (body.currency || 'USD').toUpperCase(),
    tax_rate_percent: total > 0 ? Math.round((tax / net) * 100) : 0,
    status: 'PARSED'
  }
}];

// Tax compliance & audit checks
const inv = $json;
const anomalies = [];

if (inv.total_amount <= 0) {
  anomalies.push('Zero or negative total amount');
}
if (inv.currency === 'INR' && inv.tax_rate_percent !== 18 && inv.tax_rate_percent !== 0 && inv.tax_rate_percent !== 12 && inv.tax_rate_percent !== 28) {
  anomalies.push('Non-standard GST rate detected: ' + inv.tax_rate_percent + '%');
}
if (inv.currency === 'USD' && inv.total_amount > 2500) {
  anomalies.push('High value transaction requires manual controller sign-off');
}

return [{
  json: {
    ...inv,
    has_anomalies: anomalies.length > 0,
    anomalies: anomalies,
    reconciled: anomalies.length === 0
  }
}];

